public ProducerRecord<String, String> buildRecord(String orderId, String payload) {
    // la cle (orderId) fixe la partition : hash(orderId) % partitions
    // -> tous les evenements d'une meme commande vont dans la meme partition, donc ordonnes
    return new ProducerRecord<>("commandes", orderId, payload);
}
